import React, {FC} from 'react'

interface CreateButtonProps {
    name: string;
    CreateModal: () => void;
}

const CreateButton: FC<CreateButtonProps> = (props) => {
    const handleClick = () => {
        props.CreateModal();
    };
    return (
        <button className={'create-reminder'} onClick={handleClick}>{props.name}</button>
    );
};

export default CreateButton;
